import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import "react-datepicker/dist/react-datepicker.css";
import { useParams } from "react-router-dom";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import CustomFileUploads from "src/views/common/CustomFileUploads";

const validationSchema = yup.object().shape({
  title: yup.string().trim().required("Please Enter Title."),
  // .max(100, "Title must be at most 100 characters."),
  // resources_link: yup
  //   .string()
  //   .trim()
  //   .required("Please Enter Link.")
  //   .url("Please Enter a Valid URL."),
});

const DialogResourcesDetails = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess, itSolutionOverviewId } =
    props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");
  const { id } = useParams();
  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      title: "",
      resources_link: "",
      resources_image: "",
      resources_pdf: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });
  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add" : "Edit");

      reset({
        title: dataToEdit?.title || "",
        resources_link: dataToEdit?.resources_link || "",
        resources_image: dataToEdit?.resources_image || "",
        resources_pdf: dataToEdit?.resources_pdf || "",
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    const payload = new FormData();
    payload.append("title", data.title);
    payload.append("resources_link", data.resources_link);
    payload.append("resources_image", data.resources_image);
    payload.append("resources_pdf", data.resources_pdf);
    payload.append("it_solution_resources_id", id);

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionResourcesDetails.edit(dataToEdit.id),
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionResourcesDetails.create,
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    }

    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="plan-service-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel htmlFor="title" error={Boolean(errors.title)}>
                    Title
                  </FormLabel>
                  <Controller
                    name="title"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Title"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="title"
                        value={value}
                        error={Boolean(errors.title)}
                      />
                    )}
                  />
                  {errors.title && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    htmlFor="resources_link"
                    error={Boolean(errors.resources_link)}
                  >
                    Link
                  </FormLabel>
                  <Controller
                    name="resources_link"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Link"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="resources_link"
                        value={value}
                        error={Boolean(errors.resources_link)}
                      />
                    )}
                  />
                  {errors.resources_link && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.resources_link.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel htmlFor="resources_image">
                    Resources Image
                  </FormLabel>
                  <Controller
                    name="resources_image"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <CustomFileUploads
                        multiple={false}
                        minHeight="0px"
                        subtitle="(Max file size 3mb)"
                        files={value}
                        onChange={onChange}
                        // onChange={(files) => {
                        //   const file = files?.[0] || null; // Handle no file case
                        //   onChange(file); // Update form state
                        // }}
                        title={"Add Image"}
                        // MediaUrl={MEDIA_URL}
                      />
                    )}
                  />
                  {/* {errors.icon_image && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.icon_image.message}
                    </FormHelperText>
                  )} */}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel htmlFor="resources_pdf">Resources PDF</FormLabel>
                  <Controller
                    name="resources_pdf"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <CustomFileUploads
                        multiple={false}
                        minHeight="0px"
                        subtitle="(Max file size 3mb)"
                        files={value}
                        onChange={onChange}
                        title={"Upload PDF"}

                        // MediaUrl={MEDIA_URL}
                      />
                    )}
                  />
                  {/* {errors.icon_image && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.icon_image.message}
                    </FormHelperText>
                  )} */}
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="plan-service-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogResourcesDetails;
